export const MESSAGES: MessageDictionary = {
  zh: { ...LEGACY_MESSAGES.zh, ...EXTRA.zh },
  en: { ...LEGACY_MESSAGES.en, ...EXTRA.en },
};

export function translate(lang: Lang, key: string): string {
  return MESSAGES[lang][key] ?? MESSAGES.zh[key] ?? key;
}
